// ============================================================================
// public/src/features/lesson/lesson-ai-quiz.js
// EPHEMERAL AI QUIZ — a temporary, in-page-only practice quiz generated by
// the lesson AI Agent via the shared `create_quiz` tool.
// ============================================================================
// IMPORTANT — this reads the SAME tool schema the home page's real
// create_quiz uses (see api/ai-agent/_tools.js's CREATE_QUIZ_TOOL): each
// question arrives as { q, options?, correct?, multiSelect?, answer?,
// explanation? }, never as { question, type, correctAnswer, ... }. There is
// no per-question `type` field in that schema at all — the tool call shape
// only distinguishes two kinds of question:
//   - a CHOICE question: `options` + `correct` (an array of 0-based
//     indices) are present. `multiSelect` says whether more than one can be
//     picked. This is how both "multiple choice" and "true/false" arrive —
//     true/false is just a 2-option single-select choice question.
//   - a FREE-TEXT question: no `options`/`correct`, only `answer`. This is
//     how both "fill-in-the-blank" and "short answer" arrive (the lesson
//     system prompt describes four types to the reader, but the tool itself
//     only has these two underlying shapes — grading follows the shape it
//     actually receives rather than inventing a fourth field the tool never
//     sends).
// Never a saved quiz: no `quizzes`/`user_quizzes` row is ever written from
// this module, and nothing here calls saveNewUserQuiz(). Held as in-memory
// module state for the page session only — see lesson-view.js's paint().
// ============================================================================

import { escapeHtml } from "../home/escape-html.js";

/** Normalizes free text for fill-blank/short-answer comparison: trims,
 * lowercases (locale-aware, so Arabic case folding also works where it
 * applies), and collapses internal whitespace runs to a single space. */
const norm = (v) => String(v ?? "").trim().toLocaleLowerCase().replace(/\s+/g, " ");

let activeQuiz = null;

/**
 * Validates and normalizes one raw question from the tool call into the
 * shape this module renders/grades. Returns null for anything malformed
 * rather than throwing, so one bad question doesn't sink the whole quiz —
 * createLessonQuiz() below filters nulls and only fails if NONE remain.
 */
function normalizeQuestion(raw, index) {
  if (!raw || typeof raw !== "object") return null;
  const text = String(raw.q ?? "").trim();
  if (!text) return null;

  const hasChoices = Array.isArray(raw.options) && raw.options.length >= 2 && Array.isArray(raw.correct);
  if (hasChoices) {
    const options = raw.options.slice(0, 10).map((o) => String(o ?? ""));
    // Indices must be valid positions in `options` — an out-of-range or
    // non-numeric index would otherwise grade as "always wrong" silently.
    const correct = raw.correct
      .map((i) => Number(i))
      .filter((i) => Number.isInteger(i) && i >= 0 && i < options.length);
    if (correct.length === 0) return null;
    return {
      id: `q${index}`,
      kind: "choice",
      question: text.slice(0, 2000),
      options,
      correct,
      multiSelect: Boolean(raw.multiSelect) || correct.length > 1,
      explanation: String(raw.explanation ?? "").slice(0, 2000),
    };
  }

  // Free-text: fill-in-the-blank or short answer, both graded the same way
  // — normalized exact match against `answer`. No semantic grading is ever
  // claimed (see renderFeedback() below).
  const answer = String(raw.answer ?? "").trim();
  if (!answer) return null;
  return {
    id: `q${index}`,
    kind: "text",
    question: text.slice(0, 2000),
    answer: answer.slice(0, 500),
    explanation: String(raw.explanation ?? "").slice(0, 2000),
  };
}

/**
 * Builds a new ephemeral quiz from a create_quiz tool call's input.
 *
 * Never silently discards an in-progress attempt (plan Phase 2 step 7): if
 * the reader has already answered at least one question in the current
 * quiz and hasn't graded it yet, this throws instead of overwriting — the
 * caller (lesson-view.js's handleLessonAgentToolCall) surfaces that as a
 * message asking the reader to finish or close the current one first,
 * rather than the model silently wiping their progress.
 *
 * @param {object} input - raw create_quiz tool call input
 * @returns {{title:string, questions:object[], answers:object, graded:boolean, current:number}}
 */
export function createLessonQuiz(input = {}) {
  if (activeQuiz && !activeQuiz.graded && Object.keys(activeQuiz.answers).length > 0) {
    throw new Error(
      "هناك تدريب قيد الإجابة بالفعل في هذه الصفحة. أنهِ التحقق من إجاباته أو أغلقه أولاً قبل إنشاء تدريب جديد.",
    );
  }

  const questions = (Array.isArray(input.questions) ? input.questions : [])
    .slice(0, 50)
    .map(normalizeQuestion)
    .filter(Boolean);
  if (!questions.length) throw new Error("لا توجد أسئلة صالحة لإنشاء تدريب.");

  activeQuiz = {
    title: String(input.title || "تدريب سريع من الدرس").slice(0, 160),
    questions,
    answers: {},
    graded: false,
    current: 0,
  };
  return activeQuiz;
}

function isAnswered(q, value) {
  if (value === undefined || value === null || value === "") return false;
  if (q.kind === "choice" && q.multiSelect) return Array.isArray(value) && value.length > 0;
  return true;
}

function isCorrect(q, value) {
  if (q.kind === "choice") {
    if (q.multiSelect) {
      const picked = Array.isArray(value) ? value.map(Number).sort() : [];
      const expected = [...q.correct].sort();
      return picked.length === expected.length && picked.every((v, i) => v === expected[i]);
    }
    return q.correct.length === 1 && Number(value) === q.correct[0];
  }
  return norm(value) !== "" && norm(value) === norm(q.answer);
}

function renderQuestionNav(quiz) {
  if (quiz.questions.length < 2) return "";
  const items = quiz.questions
    .map((q, i) => {
      const answered = isAnswered(q, quiz.answers[q.id]);
      const classes = ["lesson-ai-quiz__nav-dot"];
      if (i === quiz.current) classes.push("is-active");
      if (answered) classes.push("is-answered");
      return (
        `<button type="button" class="${classes.join(" ")}" data-quiz-goto="${i}" ` +
        `aria-current="${i === quiz.current ? "true" : "false"}" aria-label="سؤال ${i + 1}">${i + 1}</button>`
      );
    })
    .join("");
  return `<div class="lesson-ai-quiz__nav" role="tablist" aria-label="أسئلة التدريب">${items}</div>`;
}

function renderChoiceControl(q, value, graded) {
  const inputType = q.multiSelect ? "checkbox" : "radio";
  const picked = q.multiSelect ? (Array.isArray(value) ? value.map(String) : []) : String(value ?? "");
  return (
    `<div class="lesson-ai-quiz__options">` +
    q.options
      .map((opt, i) => {
        const checked = q.multiSelect ? picked.includes(String(i)) : picked === String(i);
        const isCorrectOpt = graded && q.correct.includes(i);
        const cls = graded
          ? `lesson-ai-quiz__option${isCorrectOpt ? " is-correct-option" : checked ? " is-wrong-option" : ""}`
          : "lesson-ai-quiz__option";
        return (
          `<label class="${cls}">` +
          `<input type="${inputType}" name="${q.id}" value="${i}" ${checked ? "checked" : ""} ${graded ? "disabled" : ""}> ` +
          `${escapeHtml(opt)}</label>`
        );
      })
      .join("") +
    `</div>`
  );
}

function renderTextControl(q, value, graded) {
  return (
    `<input class="lesson-ai-quiz__text" type="text" data-answer="${q.id}" ` +
    `value="${escapeHtml(value || "")}" ${graded ? "disabled" : ""} aria-label="الإجابة" ` +
    `placeholder="اكتب إجابتك هنا">`
  );
}

function renderFeedback(q, value, graded) {
  if (!graded) return "";
  const correct = isCorrect(q, value);
  const referenceAnswer = q.kind === "choice"
    ? q.correct.map((i) => q.options[i]).join("، ")
    : q.answer;
  // Free-text answers never claim semantic grading — the reader is shown
  // the reference answer either way, since normalized-exact-match can miss
  // a phrasing that is really correct.
  const label = q.kind === "text"
    ? (correct ? "مطابقة للإجابة المرجعية" : "غير مطابقة — قارن إجابتك بالمرجعية")
    : (correct ? "إجابة صحيحة" : "إجابة غير صحيحة");
  return (
    `<p class="lesson-ai-quiz__feedback ${correct ? "is-correct" : "is-incorrect"}">` +
    `<strong>${label}.</strong> الإجابة المرجعية: ${escapeHtml(referenceAnswer)}` +
    (q.explanation ? ` — ${escapeHtml(q.explanation)}` : "") +
    `</p>`
  );
}

/** Renders the active quiz, or "" when none is active. lesson-view.js
 * concatenates this into paint()'s output on every rerender. */
export function renderLessonQuiz() {
  if (!activeQuiz) return "";
  const quiz = activeQuiz;
  const total = quiz.questions.length;
  const answeredCount = quiz.questions.filter((q) => isAnswered(q, quiz.answers[q.id])).length;
  const current = quiz.questions[Math.min(quiz.current, total - 1)];
  const value = quiz.answers[current.id];

  const control = current.kind === "choice"
    ? renderChoiceControl(current, value, quiz.graded)
    : renderTextControl(current, value, quiz.graded);

  const score = quiz.questions.filter((q) => isCorrect(q, quiz.answers[q.id])).length;

  const progressLabel = quiz.graded
    ? `النتيجة: ${score} / ${total}`
    : `أُجيب عن ${answeredCount} من ${total}`;

  const prevBtn = `<button type="button" class="lesson-ai-quiz__step" data-quiz-prev ${quiz.current === 0 ? "disabled" : ""}>السابق</button>`;
  const nextBtn = `<button type="button" class="lesson-ai-quiz__step" data-quiz-next ${quiz.current >= total - 1 ? "disabled" : ""}>التالي</button>`;

  return (
    `<section class="lesson-ai-quiz" aria-label="تدريب من الدرس">` +
    `<header class="lesson-ai-quiz__header">` +
    `<div><h2>${escapeHtml(quiz.title)}</h2><p class="lesson-ai-quiz__hint">تدريب مؤقت — لا يُضاف إلى امتحاناتك</p></div>` +
    `<button type="button" class="lesson-ai-quiz__close" data-quiz-close aria-label="إغلاق التدريب">×</button>` +
    `</header>` +
    renderQuestionNav(quiz) +
    `<p class="lesson-ai-quiz__progress">${progressLabel}</p>` +
    `<fieldset class="lesson-ai-quiz__question">` +
    `<legend>${quiz.current + 1}. ${escapeHtml(current.question)}</legend>` +
    control +
    renderFeedback(current, value, quiz.graded) +
    `</fieldset>` +
    `<footer class="lesson-ai-quiz__footer">` +
    `<div class="lesson-ai-quiz__steps">${prevBtn}${nextBtn}</div>` +
    (quiz.graded
      ? `<button type="button" class="lesson-ai-quiz__submit" data-quiz-reset>إعادة المحاولة</button>`
      : `<button type="button" class="lesson-ai-quiz__submit" data-quiz-grade ${answeredCount === 0 ? "disabled" : ""}>تحقق من الإجابات</button>`
    ) +
    `</footer>` +
    `</section>`
  );
}

/** Wires the active quiz's interactions. Called after every paint(). */
export function equipLessonQuiz(root, rerender) {
  const section = root.querySelector(".lesson-ai-quiz");
  if (!section || !activeQuiz) return;
  const quiz = activeQuiz;

  section.querySelector("[data-quiz-close]")?.addEventListener("click", () => {
    activeQuiz = null;
    rerender();
  });

  section.querySelectorAll('input[type="radio"][name^="q"]').forEach((el) => {
    el.addEventListener("change", () => {
      quiz.answers[el.name] = el.value;
      rerender();
    });
  });
  section.querySelectorAll('input[type="checkbox"][name^="q"]').forEach((el) => {
    el.addEventListener("change", () => {
      const checked = Array.from(
        section.querySelectorAll(`input[type="checkbox"][name="${CSS.escape(el.name)}"]:checked`),
      ).map((c) => c.value);
      quiz.answers[el.name] = checked;
      rerender();
    });
  });
  section.querySelectorAll("[data-answer]").forEach((el) => {
    el.addEventListener("input", () => {
      quiz.answers[el.dataset.answer] = el.value;
    });
    // Blur (not every keystroke) triggers a rerender for text inputs, so
    // the progress count updates without fighting the caret position.
    el.addEventListener("blur", () => rerender());
  });

  section.querySelector("[data-quiz-prev]")?.addEventListener("click", () => {
    quiz.current = Math.max(0, quiz.current - 1);
    rerender();
  });
  section.querySelector("[data-quiz-next]")?.addEventListener("click", () => {
    quiz.current = Math.min(quiz.questions.length - 1, quiz.current + 1);
    rerender();
  });
  section.querySelectorAll("[data-quiz-goto]").forEach((btn) => {
    btn.addEventListener("click", () => {
      quiz.current = Number(btn.dataset.quizGoto) || 0;
      rerender();
    });
  });

  section.querySelector("[data-quiz-grade]")?.addEventListener("click", () => {
    quiz.graded = true;
    rerender();
  });
  section.querySelector("[data-quiz-reset]")?.addEventListener("click", () => {
    quiz.answers = {};
    quiz.graded = false;
    quiz.current = 0;
    rerender();
  });
}

/** True while a quiz is active. Exported for lesson-view.js if it needs to
 * know whether a temp quiz is currently occupying the page. */
export function hasActiveLessonQuiz() {
  return activeQuiz !== null;
}
